#include <stdlib.h>
#include <string.h>

// Define a structure for private data
typedef struct {
    int32_t* buffer;
    size_t capacity;
    size_t used;
} PrivateData;

FLAC__StreamDecoderWriteStatus write_callback(
    const FLAC__StreamDecoder* decoder,
    const FLAC__Frame* frame,
    const int32_t* const buffer[],
    void* client_data
) {
    // Cast client_data to our private data structure
    PrivateData* data = (PrivateData*)client_data;
    if (!data) {
        return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
    }

    // Calculate the number of samples in this frame
    size_t samples = frame->header.blocksize;
    size_t channels = frame->header.channels;

    // Calculate the total number of samples to copy
    size_t total_samples = samples * channels;

    // Calculate the required capacity
    size_t required_capacity = data->used + total_samples;

    // If we need to grow the buffer
    if (required_capacity > data->capacity) {
        // Calculate the new capacity (double the current or 16, whichever is larger)
        size_t new_capacity = data->capacity ? data->capacity * 2 : 16;
        while (new_capacity < required_capacity) {
            new_capacity *= 2;
        }

        // Allocate new buffer
        int32_t* new_buffer = (int32_t*)realloc(data->buffer, new_capacity * sizeof(int32_t));
        if (!new_buffer) {
            return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
        }

        data->buffer = new_buffer;
        data->capacity = new_capacity;
    }

    // Copy the samples from the buffer
    for (size_t i = 0; i < samples; i++) {
        for (size_t ch = 0; ch < channels; ch++) {
            if (data->used < data->capacity) {
                data->buffer[data->used++] = buffer[ch][i];
            }
        }
    }

    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}
